package android.util;import java.io.*;public class AtomicFile{private File file,tmp;public AtomicFile(File f){file=f;tmp=new File(f+".new");}public File getBaseFile(){return file;}public FileOutputStream startWrite()throws IOException{file.getParentFile().mkdirs();return new FileOutputStream(tmp);}public void finishWrite(FileOutputStream out){try{out.close();java.nio.file.Files.move(tmp.toPath(),file.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}catch(IOException e){throw new RuntimeException(e);}}public void failWrite(FileOutputStream out){try{out.close();}catch(IOException ignored){}tmp.delete();}public FileInputStream openRead()throws IOException{return new FileInputStream(file);}}
